import * as React from 'react'
import { createPortal } from 'react-dom'
import { motion } from 'motion/react'
import { cn } from '@/lib/utils'

export interface PopoverProps {
  trigger: React.ReactNode
  children: React.ReactNode
  align?: 'start' | 'center' | 'end'
  side?: 'top' | 'bottom' | 'left' | 'right'
  sideOffset?: number
  className?: string
  closeOnClickOutside?: boolean
}

export function Popover({
  trigger,
  children,
  align = 'center',
  side = 'bottom',
  sideOffset = 10,
  className,
  closeOnClickOutside = true,
}: PopoverProps) {
  const [open, setOpen] = React.useState(false)
  const triggerRef = React.useRef<HTMLDivElement>(null)
  const panelRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    if (!open) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false)
    }
    const onClickOutside = (event: MouseEvent) => {
      if (!closeOnClickOutside) return
      const target = event.target as Node
      if (!triggerRef.current?.contains(target) && !panelRef.current?.contains(target)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', onClickOutside)
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('mousedown', onClickOutside)
      document.removeEventListener('keydown', onKeyDown)
    }
  }, [open, closeOnClickOutside])

  if (typeof document === 'undefined') return null

  const triggerRect = triggerRef.current?.getBoundingClientRect()
  const panelStyle: React.CSSProperties = {
    zIndex: 60,
    position: 'absolute',
  }
  if (triggerRect) {
    if (side === 'bottom') {
      panelStyle.top = triggerRect.bottom + sideOffset
      panelStyle.left =
        align === 'start'
          ? triggerRect.left
          : align === 'end'
          ? triggerRect.right
          : triggerRect.left + triggerRect.width / 2
      if (align === 'end') panelStyle.transform = 'translateX(-100%)'
      if (align === 'center') panelStyle.transform = 'translateX(-50%)'
    } else if (side === 'top') {
      panelStyle.bottom = window.innerHeight - triggerRect.top + sideOffset
      panelStyle.left =
        align === 'start'
          ? triggerRect.left
          : align === 'end'
          ? triggerRect.right
          : triggerRect.left + triggerRect.width / 2
      if (align === 'end') panelStyle.transform = 'translateX(-100%)'
      if (align === 'center') panelStyle.transform = 'translateX(-50%)'
    } else if (side === 'left') {
      panelStyle.right = window.innerWidth - triggerRect.left + sideOffset
      panelStyle.top = triggerRect.top + triggerRect.height / 2
      panelStyle.transform = 'translateY(-50%)'
    } else {
      panelStyle.left = triggerRect.right + sideOffset
      panelStyle.top = triggerRect.top + triggerRect.height / 2
      panelStyle.transform = 'translateY(-50%)'
    }
  }

  return (
    <div className="relative inline-flex">
      <div ref={triggerRef} className="inline-flex">
        {React.isValidElement(trigger)
          ? React.cloneElement(trigger as React.ReactElement<{ onClick?: () => void }>, {
              onClick: (event: React.MouseEvent) => {
                trigger.props?.onClick?.(event)
                setOpen((prev) => !prev)
              },
            })
          : trigger}
      </div>
      {open &&
        createPortal(
          <motion.div
            ref={panelRef}
            role="dialog"
            aria-label="Popover"
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ type: 'spring', stiffness: 500, damping: 30 }}
            style={panelStyle}
            className={cn(
              'w-64 rounded-2xl bg-white p-4 font-sans rk-border rk-shadow-lg',
              className
            )}
          >
            {children}
          </motion.div>,
          document.body
        )}
    </div>
  )
}
